SELECT p.id AS paper_id, m.id, m.observed_at, m.price, m.delivery_status, m.outcome_reason, m.created_at FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event m ON m.symbol = p.symbol AND m.observed_at BETWEEN (CASE p.id WHEN 137 THEN '2026-10-11 21:00:00' WHEN 158 THEN '2026-10-12 03:30:00' WHEN 172 THEN '2026-10-12 07:15:00' WHEN 182 THEN '2026-10-12 10:05:00' END) AND p.closed_at + INTERVAL 3 SECOND WHERE p.id IN (137,158,172,182) ORDER BY p.id, m.observed_at, m.id LIMIT 300;